.details-scene pre,
.details-status pre,
.details-mem pre,
.actions .item,
.env,
.bet-body,
.lq-body,
.ry-text,
.txt-n,
.txt-n-break,
.txt-az,
.txt-ll,
.txt-yy,
.txt-ww,
.txt-mm,
.txt-lan,
.txt-tt,
.txt-x,
.txt-duo,
.txt-lu,
.txt-nuo,
.txt-mei,
.txt-xiao,
.txt-shen,
.txt-wan,
.txt-zhi,
.txt-bo,
.txt-sys,
.txt-target,
.txt-wei,
.txt-qiang,
.txt-qing,
.txt-mian,
.txt-xi,
.txt-yao,
.txt-man,
.txt-xu,
.txt-gu,
.txt-ke,
.txt-ling,
.txt-yu,
.txt-app,
